from test_bufftap import test, tests
from test_nearby import setup
# 1.19.4: ideas from similar addons.
B="local B=BuffTap; "
test('Blacklist blocks named players, ignored players and guilds',B+"assert(not B:BlockReason('target')); B:SetBlocked('player',' Ally ',true); assert(B.db.blockedPlayers.ally and B:BlockReason('target')=='blacklisted player'); B:SetBlocked('player','Ally',false); assert(not B:BlockReason('target')); C_FriendList={IsIgnored=function(n) return n=='Ally' end}; assert(B:BlockReason('target')=='on your ignore list'); B.db.blockIgnored=false; assert(not B:BlockReason('target')); C_FriendList=nil; GetGuildInfo=function() return 'Loud Guild' end; B:SetBlocked('guild','loud guild',true); assert(B:BlockReason('target')=='blacklisted guild'); local f,why=B:FriendlyTargetEntry('target'); assert(not f)")
test('Blacklist settings normalize and survive bad saved data',B+"B.db.blockedPlayers={ok=true,bad=5,[3]=true}; B.db.blockedGuilds='x'; B:InitDB(); assert(B.db.blockedPlayers.ok and B.db.blockedPlayers.bad==nil and B.db.blockedPlayers[3]==nil and type(B.db.blockedGuilds)=='table'); B:ShowBlacklist(); assert(B.options:IsShown() and B.options.activeTab==13 and B.options.pages[13]:IsShown()); B.db.blockedPlayers={}; B.db.blockedGuilds={}; B:SetBlocked('player','Zed',true); B:SetBlocked('player','Amy',true); B:SetBlocked('guild','Loud',true); local p,g=B.options.blackLists[1],B.options.blackLists[2]; assert(p.rows[1].name=='amy' and p.rows[2].name=='zed' and g.rows[1].name=='loud' and not p.empty:IsShown()); p.rows[1].remove.scripts.OnClick(p.rows[1].remove); assert(not B.db.blockedPlayers.amy and p.rows[1].name=='zed' and not p.rows[2]:IsShown())")
test('Mana floor stops buffing other players but reports why',B+"UnitPower=function() return 20 end; UnitPowerMax=function() return 100 end; B.db.nearbyManaFloor=30; assert(B:ManaFloorReached()); B.db.friendlyTarget=true; local e,why=B:FriendlyTargetEntry('target'); assert(not e and why=='saving mana' and B.powerBlocked); UnitPower=function() return 50 end; assert(not B:ManaFloorReached()); B.db.nearbyManaFloor=33; B:InitDB(); assert(B.db.nearbyManaFloor==35); B.db.nearbyManaFloor=80; B:InitDB(); assert(B.db.nearbyManaFloor==50)")
test('Consumables can be limited to dungeons and raids',B+"B.db.consumablesInstanceOnly=true; IsInInstance=function() return false,'none' end; assert(B:CategoryRestingPause('consumables')=='paused outside dungeons and raids'); IsInInstance=function() return true,'party' end; assert(not B:CategoryRestingPause('consumables')); IsInInstance=function() return true,'pvp' end; assert(B:CategoryRestingPause('consumables')); assert(not B:CategoryRestingPause('weapons'))")
test('A timed dismiss expires on its own',B+"B.db.helperDismissMinutes=5; local a={id=1459,target='player',name='Arcane Intellect'}; B:DismissHelper(a); assert(B:HelperSuppressed(a)); now=now+301; assert(not B:HelperSuppressed(a)); B.db.helperDismissMinutes=0; B:DismissHelper(a); now=now+10000; assert(B:HelperSuppressed(a)); B:RestoreHelpers(); assert(not B:HelperSuppressed(a))")
test('Ready check and dungeon top-ups raise the refresh window',B+"assert(B:EarlyTopUpSeconds(60,1800)==60); B.readyCheckUntil=now+40; assert(B:EarlyTopUpSeconds(60,300)==150 and B:EarlyTopUpSeconds(60,1800)==300); B.db.readyCheckTopUp=false; assert(B:EarlyTopUpSeconds(60,300)==60); B.readyCheckUntil=nil; IsInInstance=function() return true,'raid' end; assert(B:EarlyTopUpSeconds(60,1800)==180 and B:EarlyTopUpSeconds(60,600)==60)")
test('Pets join the roster only when enabled and never take group spells',B+"local old=UnitExists; UnitExists=function(u) return u=='pet' or old(u) end; UnitIsDeadOrGhost=function() return false end; B:InvalidateRoster(); local function hasPet() for _,e in ipairs(B:Roster()) do if e.pet then return e end end end; assert(not hasPet()); B.db.buffPets=true; B:InvalidateRoster(); local p=hasPet(); assert(p and p.unit=='pet'); assert(B:RecipientAllowed({kind='single'},p) and not B:RecipientAllowed({kind='blessing'},p) and not B:GroupRecipientAllowed({kind='single'},p)); UnitExists=old")
test('Unending Breath waits for the breath timer',B+"local def=B:FindBuff('unending-breath'); local miss,why=B:Missing(def,{id=5697,name='Unending Breath'},{}); assert(miss==false and why=='not underwater'); B.underwater=true; miss=B:Missing(def,{id=5697,name='Unending Breath'},{}); assert(miss==true)")
test('Settings export and import round-trip, refusing other classes for buff setup',B+"B.db.nearbyFullNames=false; B.db.buffs.ai=false; B.db.requestMessage='Hi \"there\"|x'; local s=B:ExportSettings(); assert(s:match('^BuffTap1:')); B.db.nearbyFullNames=true; B.db.buffs.ai=true; local ok,msg=B:ImportSettings(s); assert(ok and B.db.nearbyFullNames==false and B.db.buffs.ai==false and msg=='Imported settings.'); local other=s:gsub('^BuffTap1:%u+:','BuffTap1:WARRIOR:'); B.db.buffs.ai=true; B.db.consumablesInstanceOnly=false; ok,msg=B:ImportSettings(other); assert(ok and B.db.buffs.ai==true and msg:find('skipped')); assert(not B:ImportSettings('BuffTap1:MAGE:{\"a\"=os.exit()}')); assert(not B:ImportSettings('hello'))")
test('Diagnostics page captures command output and hides names',B+"B:Options(); B:ShowReport('debug'); local f=B.options; assert(f.activeTab==11 and f.discoveryScroll:IsShown() and f.discoveryReport:GetText():find('BuffTap')); local before=#prints; local h=B:ReportText('status',true); assert(not h:find('Tester') and #prints==before and B.outputCapture==nil)")
test('Blacklist rules: own targets and dungeons',B+"B:SetBlocked('player','Ally',true); B.db.friendlyTarget=true; local e,why=B:FriendlyTargetEntry('target'); assert(not e and why=='blacklisted player'); B.db.blacklistTargets=false; e,why=B:FriendlyTargetEntry('target'); assert(why~='blacklisted player'); IsInInstance=function() return true,'party' end; B.db.blacklistInInstances=false; assert(not B:BlockReason('target')); B.db.blacklistInInstances=true; assert(B:BlockReason('target'))")
test('Nearby right-click menu offers blacklist actions',setup+"local row=BuffTap.nearbyFrame.rows[1]; row.entry={name='Ally',unit='target'}; GetGuildInfo=function() return 'Loud' end; BuffTap:ShowNearbyMenu(row); local m=BuffTap.nearbyMenu; assert(m:IsShown() and m.items[5].text:GetText():find('Loud')); m.items[4].scripts.OnClick(m.items[4]); assert(BuffTap.db.blockedPlayers.ally and not m:IsShown())")
test('Water Breathing and Aquatic Form wait for the breath timer',B+"B.underwater=nil; for _,key in ipairs({'water-breathing','aquatic-form'}) do local def=B:FindBuff(key); assert(def and def.underwater); local miss,why=B:Missing(def,{id=def.ranks[1],name=def.name},{}); assert(miss==false and why=='not underwater') end; local wb=B:FindBuff('water-breathing'); assert(B:Missing(wb,{id=131,name='Water Breathing',target='target'},{})==true); assert(B:Missing(wb,{id=131,name='Water Breathing',target='party1'},{})==false); local aq=B:FindBuff('aquatic-form'); assert(B:Missing(aq,{id=1066,name='Aquatic Form',target='target'},{})==false)")
test('A Nearby key takes nearby buffs off the main key',B+"B.db.nearbyKeys={'F'}; B:InitDB(); assert(B.db.nearbyKeys[1]=='F'); assert(not B:NearbyOnMainKey()); B.db.nearbyKeys={}; assert(B:NearbyOnMainKey()); B:Options(); B:CaptureBinding('nearby'); assert(B.capture.target=='nearby')")
test('Thank delay waits a random moment inside the thank window',B+"B.db.helperThankDelay=2; B:InitDB(); assert(B.db.helperThankDelay==2); B.db.helperThankDelay=9; B:InitDB(); assert(B.db.helperThankDelay==0)")
test('Pause note is said once per zone when buff data is unreadable',B+"local n=#prints; B.buffDataUnavailable=nil; B.pauseNoteShown=true; refresh(); assert(#prints==n)")
test('1.20.0 defaults: party buffing turns on once, dismiss only for new characters',B+"B.db.group=false; B.db.groupDefaultVersion=nil; B:InitDB(); assert(B.db.group==true and B.db.groupDefaultVersion==1); B.db.group=false; B:InitDB(); assert(B.db.group==false); B.db.helperDismiss=false; B.db.helperDismissMinutes=nil; B:InitDB(); assert(B.db.helperDismiss==false and B.db.helperDismissMinutes==0); B.db.helperDismiss=nil; B.db.helperDismissMinutes=nil; B:InitDB(); assert(B.db.helperDismiss==true and B.db.helperDismissMinutes==10)")
test('Move BuffTap frames shows movers and Done restores options',B+"B:MoveAllFrames(); assert(B.editModeActive and B.moveDoneBar:IsShown()); B:FinishMovingFrames(); assert(not B.editModeActive and not B.moveDoneBar:IsShown() and B.options:IsShown())")
test('Login and loading screens wait a moment before reminding',"assert(BuffTap.action); BuffTap.events.scripts.OnEvent(nil,'PLAYER_ENTERING_WORLD'); assert(not BuffTap.action and BuffTap:ReminderPauseReason()=='loading'); advance(4.2); assert(BuffTap.action and not BuffTap.loadingUntil)")
test('Aquatic Form shows no rebuff timing',"playerClass='DRUID'; local B=BuffTap; B:InitDB(); B.db.buffs['aquatic-form']=true; B:Options(); local found=false; for _,row in ipairs(B.options.buffRows or {}) do if row.def and row.def.key=='aquatic-form' then found=true; assert(not row.rebuff:IsShown()) end end; assert(B:FindBuff('aquatic-form').stance)")
test('Natures Grasp reminds only when gone and Aquatic Form sorts last',B+"local ng=B:FindBuff('natures-grasp'); assert(ng.noTimer); local keys={}; for i,b in ipairs(B.Buffs) do if b.class=='DRUID' then keys[#keys+1]=b.key end end; assert(keys[#keys]=='aquatic-form')")
test('Default timing follows buff length',"BuffTap.db.buffs.thorns=false; aura('player',5232,'Mark of the Wild',200,1800); refresh(); assert(not BuffTap.action); auras.player={}; aura('player',5232,'Mark of the Wild',200,3600); refresh(); assert(BuffTap.action and BuffTap.action.id==5232); BuffTap.db.buffSeconds.motw=60; BuffTap:InvalidateAura(); refresh(); assert(not BuffTap.action)")
test('Party timing uses the length rules and targets keep their refresh',"BuffTap.db.buffs.thorns=false; aura('player',5232,'Mark of the Wild',200,3600); refresh(); assert(BuffTap.action and BuffTap.action.id==5232); local def=BuffTap:FindBuff('motw'); auras.player={}; aura('player',5232,'Mark of the Wild',200,1800); local list=BuffTap:ScanMissing(def,{{unit='player',class='DRUID'}},{},{},300); assert(#list==1)")
test('New icon effects run and urgency colour follows the refresh window',"local B=BuffTap; for _,style in ipairs({'shine','ripple','bounce','orbit'}) do B.db.effectStyle=style; B:InitDB(); assert(B.db.effectStyle==style); B:ApplyIconEffect(B.button,true); B:StopIconEffect(B.button) end; B.db.effectStyle='bogus'; B:InitDB(); assert(B.db.effectStyle==nil); B.db.effectUrgency=true; B.action={needState='missing'}; assert(B:EffectUrgency(B.button,B.db)=='red'); B.action={needState='expiring',remaining=10,threshold=45,selectedAt=now}; assert(B:EffectUrgency(B.button,B.db)=='amber'); B.action={needState='expiring',remaining=40,threshold=45,selectedAt=now}; assert(B:EffectUrgency(B.button,B.db)==nil); B.db.effectUrgency=false; assert(B:EffectUrgency(B.button,B.db)==nil)")
test('Flash once settles to a calm glow',"local B=BuffTap; B.db.effectStyle='ripple'; B.db.effectOnce=true; B.button.buffTapEffectKey=nil; B:ApplyIconEffect(B.button,true); local key=B.button.buffTapEffectKey; advance(3.2); assert(B.button.buffTapEffectKey==key and B.button.glow.shown)")
test('Nearby markers explain blacklisted and PvP-flagged players',B+"B.db.pvpProtection=true; UnitIsPVP=function(u) return u=='target' end; UnitIsPVPFreeForAll=function() return false end; assert(B:NearbyMarker('target')=='pvp'); UnitIsPVP=function(u) return u=='player' end; assert(B:NearbyMarker('target')==nil); UnitIsPVP=function() return false end; B:SetBlocked('player','Ally',true); assert(B:NearbyMarker('target')=='blocked'); B.db.pvpProtection=false; B:SetBlocked('player','Ally',false); assert(B:NearbyMarker('target')==nil)")
test('Nearby menu offers removal for blacklisted players',setup+"GetGuildInfo=function() return 'Loud' end; BuffTap:SetBlocked('player','Ally',true); local row=BuffTap.nearbyFrame.rows[1]; row.entry={name='Ally',unit='target'}; BuffTap:ShowNearbyMenu(row); local m=BuffTap.nearbyMenu; assert(m.items[4].text:GetText()=='Remove from blacklist'); m.items[4].scripts.OnClick(m.items[4]); assert(not BuffTap.db.blockedPlayers.ally)")
test('Idle status explains why nothing needs doing',"local B=BuffTap; B.action=nil; B.reason='nothing actionable'; B.rangeBlocked=false; assert(B:FriendlyStatus()=='All your buffs are up.'); B.rangeBlocked=true; assert(B:FriendlyStatus():find('out of range')); B.rangeBlocked=false; B.db.nearbyEnabled=true; B.nearbyFrame={IsShown=function() return true end}; B.nearbyCounts={total=0,need=0}; assert(B:FriendlyStatus():find('No players nearby')); B.nearbyCounts={total=3,need=0}; assert(B:FriendlyStatus():find('Nearby players have'))")
